from construire import Chapter,fig,box,qs,sub
from nouveaux_communs import diagnostic,exercices,bilan,TD9,DS5
from math import pi,sqrt

def create():
 c=Chapter(8,'Propagation d’un signal','1.6 / ondes progressives','la propagation unidimensionnelle, le retard, la double périodicité, les déphasages et la distinction entre milieux dispersifs et non dispersifs.')
 c.f('impulsion',r'''\begin{axis}[width=13.4cm,height=5.8cm,xmin=0,xmax=10,ymin=0,ymax=1.25,xlabel={$x$ (m)},ylabel={$s/A$},axis lines=left,grid=major,legend style={draw=none,font=\small,at={(.5,1.03)},anchor=south,legend columns=2}]\addplot[otNavy,thick,domain=0:10,samples=200]{exp(-((x-2)/.65)^2)};\addlegendentry{$t=0$}\addplot[otGreenDark,thick,domain=0:10,samples=200]{exp(-((x-6)/.65)^2)};\addlegendentry{$t=2$ s, $c=2$ m/s}\end{axis}''')
 c.f('capteurs',r'''\draw[axis](0,0)--(12,0)node[right]{$x$};\node[draw=otNavy,fill=otNavyTint,minimum height=1cm]at(1,0){Source};\fill[otNavy](4,0)circle(3pt)node[above=4mm]{$A$};\fill[otGreenDark](10,0)circle(3pt)node[above=4mm]{$B$};\draw[<->,otMuted](4,-.8)--(10,-.8)node[midway,below]{$d=x_B-x_A$};\draw[-{Stealth},otNavy,thick](5.5,1)--(8.5,1)node[midway,above]{$c$};\node[lab,text width=10cm,align=center]at(6,-2){$s_B(t)=s_A(t-d/c)$\\B reçoit le même événement avec le retard $\tau=d/c$.};''')
 c.f('sinus-espace',r'''\begin{axis}[width=13.4cm,height=5.6cm,xmin=0,xmax=3,ymin=-1.3,ymax=1.3,xlabel={$x/\lambda$},ylabel={$s/A$},axis lines=left,grid=major,legend style={draw=none,at={(.5,1.04)},anchor=south,legend columns=2,font=\small}]\addplot[otNavy,thick,domain=0:3,samples=220]{cos(deg(2*pi*x))};\addlegendentry{$t=0$}\addplot[otGreenDark,thick,domain=0:3,samples=220]{cos(deg(2*pi*x-pi/2))};\addlegendentry{$t=T/4$}\end{axis}''')
 c.f('sinus-temps',r'''\begin{axis}[width=13.4cm,height=5.6cm,xmin=0,xmax=2,ymin=-1.3,ymax=1.3,xlabel={$t/T$},ylabel={$s/A$},axis lines=left,grid=major,legend style={draw=none,at={(.5,1.04)},anchor=south,legend columns=2,font=\small}]\addplot[otNavy,thick,domain=0:2,samples=220]{cos(deg(2*pi*x))};\addlegendentry{$x=0$}\addplot[otGreenDark,thick,domain=0:2,samples=220]{cos(deg(2*pi*x-pi/2))};\addlegendentry{$x=\lambda/4$}\end{axis}''')
 c.f('dispersion',r'''\begin{axis}[width=13.4cm,height=5.7cm,xmin=0,xmax=6.3,ymin=-1.9,ymax=1.9,xlabel={Phase réduite},ylabel={$s/A$},axis lines=left,grid=major,legend style={draw=none,at={(.5,1.04)},anchor=south,legend columns=2,font=\small}]\addplot[otNavy,thick,domain=0:6.3,samples=250]{cos(deg(x))+.5*cos(deg(2*x))};\addlegendentry{Profil initial}\addplot[otGreenDark,thick,domain=0:6.3,samples=250]{cos(deg(x))+.5*cos(deg(2*x-.9))};\addlegendentry{Phase relative modifiée}\end{axis}''')
 c.intro='Une perturbation émise en un point n’est pas reçue instantanément ailleurs. Dans un milieu transparent non dispersif, elle se transmet sans changer de forme : la propagation se décrit par une translation. Cette idée permet de prédire un enregistrement, mesurer une célérité et interpréter un déphasage.'
 c.mapping='Grandeurs acoustiques, électriques et électromagnétiques ; formes f(x-ct), g(x+ct), f(t-x/c), g(t+x/c) ; évolution temporelle et spatiale ; célérité, retard et vitesse de phase ; relation λf = c ; ordres de grandeur ; mesure et dispersion.'
 c.prereq='Sinusoïdes, phase, période, fréquence et lecture de graphes. Conversion des durées et longueurs. Le chapitre 7 fournit la décomposition d’un signal en composantes.'
 c.method='Identifier la grandeur et le sens de propagation ; choisir une origine ; écrire le retard ; distinguer profil spatial et enregistrement temporel ; contrôler unités et causalité ; discuter le domaine du modèle.'
 c.boundary='Conformément au programme, aucune équation d’onde n’est utilisée. Les exemples dispersifs restent descriptifs ou utilisent une loi fournie.'
 diagnostic(c,[(r'Combien vaut 0,80 ms en secondes ?',r'$8{,}0\times10^{-4}$ s.'),(r'Une perturbation parcourt 0,68 m en 2,0 ms. Calculer sa célérité.',r'$c=d/\tau=340$ m/s.'),(r'Un retard positif τ transforme f(t) en quelle fonction ?',r'$f(t-\tau)$ ; le même événement apparaît plus tard.'),(r'À f = 500 Hz, donner T et ω.',r'T = 2 ms ; $\omega=1000\pi$ rad/s.'),(r'Que vaut $\cos(\theta-2\pi)$ ?',r'$\cos\theta$ : une phase mesurée seule est ambiguë modulo $2\pi$.'),(r'Quelle grandeur oscille dans un son ?',r'Notamment la surpression acoustique par rapport à la pression d’équilibre ; les particules du milieu oscillent aussi localement.'),(r'Le son se propage-t-il dans le vide ?',r'Non ; une onde acoustique a besoin d’un milieu matériel.'),(r'Une onde progressive transporte-t-elle nécessairement le milieu avec elle ?',r'Non. Le déplacement local des particules se distingue du déplacement de la perturbation.')])
 c.c('Quel signal se propage ?',sub('Une grandeur mesurable',r'Un signal est la variation d’une grandeur physique. Dans l’air, on peut mesurer la surpression $p-p_0$ avec un microphone ; sur une corde, le déplacement transversal y ; dans un câble, une tension ou un courant ; pour la lumière, des champs électrique et magnétique. La grandeur et son unité doivent accompagner toute fonction s(x,t).')+box('loi','Onde et transport',r'Une onde décrit la propagation d’une perturbation. La célérité de la perturbation n’est pas la vitesse d’une particule du support. Une corde peut porter une bosse qui avance horizontalement alors que ses points se déplacent surtout verticalement.')+sub('Ordres de grandeur utiles',r'Le domaine audible usuel s’étend environ de 20 Hz à 20 kHz ; au-delà, on parle d’ultrasons. Les vibrations mécaniques d’une corde peuvent être de l’ordre de quelques dizaines à quelques milliers de hertz. Le visible est de l’ordre de $4\times10^{14}$ à $8\times10^{14}$ Hz. Le son dans l’air près de la température ambiante se propage vers 340 m/s ; la lumière dans le vide à $c_0=299\,792\,458$ m/s.')+box('piege','Le support et le signal',r'Une onde électromagnétique peut se propager dans le vide. Une onde sonore ne le peut pas. Ne pas attribuer la célérité de la lumière à un signal électrique dans n’importe quel câble : sa propagation dépend du guide.'))
 c.c('La translation d’un profil',fig('impulsion','Une même impulsion translatée de 4 m vers la droite en 2 s. Sa largeur et son amplitude sont conservées dans le modèle.')+box('loi','Propagation vers les x croissants',r'À t = 0, le profil est F(x). À la date t :\[s(x,t)=F(x-ct),\qquad c>0.\]Un point caractéristique vérifie $x-ct=\text{constante}$, donc se déplace à la vitesse +c. Vers les x décroissants : $s(x,t)=G(x+ct)$.')+sub('Tester le signe',r'Pour une bosse initialement centrée en $x_0$, $F(x-x_0)$ devient $F(x-x_0-ct)$ : son centre est $x_0+ct$. Ce test évite de mémoriser un signe sans comprendre. La notation F prend un argument de longueur ; elle est distincte d’une fonction source dont l’argument serait un temps.'))
 c.c('Le retard d’un événement',fig('capteurs','Deux capteurs séparés dans le sens de propagation. Le retard porte sur le même événement physique.')+box('loi','Écriture à partir de la source',r'Si la source en x = 0 émet $s(0,t)=f(t)$, la propagation vers +x donne\[s(x,t)=f(t-x/c).\]À distance x, le signal reçu à t a été émis à $t-x/c$. Entre A et B : $s_B(t)=s_A(t-\tau)$ avec $\tau=(x_B-x_A)/c$.')+sub('Causalité',r'Une source mise en route à t = 0 n’a encore rien envoyé en x si $t<x/c$. Pour une salve finie, appliquer le retard à l’enveloppe et à l’oscillation qu’elle contient. Écrire un sinus présent depuis toujours ne représente pas à lui seul le front d’allumage.'))
 c.c('Lire l’espace et le temps',sub('Deux expériences graphiques',r'Une photographie à t fixé représente s en fonction de x. Un capteur à x fixé représente s en fonction de t. Leurs axes et leurs unités diffèrent ; une largeur de profil en mètres ne peut pas être lue directement comme une durée.')+box('loi','Largeur et durée',r'Pour une impulsion se propageant sans déformation, une largeur spatiale $\ell$ correspond à une durée de passage $\Delta t=\ell/c$. Pour une propagation vers +x, les points les plus à droite du profil passent les premiers devant un capteur placé en aval.')+sub('Un exemple asymétrique',r'Un profil triangulaire s’étend de x = 1 m à x = 5 m à t = 0, avec son maximum en x = 2 m, et avance à 2 m/s. Au capteur x = 9 m, le bord droit arrive à t = 2 s, le maximum à t = 3,5 s et le bord gauche à t = 4 s. L’enregistrement monte donc pendant 1,5 s puis descend pendant 0,5 s. Il inverse l’ordre de lecture gauche-droite du profil spatial.')+box('methode','Construire sans formule',r'Suivre chaque sommet ou discontinuité avec $x(t)=x(0)+ct$. Ranger ses dates d’arrivée. Relier ensuite les hauteurs dans le bon ordre. Cette méthode fonctionne aussi pour un signal à plusieurs impulsions.'))
 c.c('L’onde progressive sinusoïdale',box('loi','Une phase qui se déplace',r'\[s(x,t)=A\cos(\omega t-kx+\varphi_0),\quad k=\omega/c>0.\]Cette écriture décrit une propagation vers +x. Une phase constante donne $\omega\dd t-k\dd x=0$, donc $\dd x/\dd t=\omega/k=c$. Vers -x, remplacer -kx par +kx.')+fig('sinus-espace','Deux photographies espacées de T/4 : le profil avance de λ/4 vers les x croissants.')+sub('Paramètres',r'A est une amplitude, $\omega$ en rad/s une pulsation et k en rad/m un nombre d’onde. L’argument du cosinus est sans dimension. La phase initiale dépend des origines choisies ; le sens de propagation ne dépend pas du signe isolé de tout l’argument, puisque le cosinus est pair.'))
 c.c('La double périodicité',fig('sinus-temps','À un point situé λ/4 plus loin, le signal retarde d’un quart de période. Les deux capteurs mesurent la même fréquence.')+box('loi','Périodes temporelle et spatiale',r'\[T=\frac{2\pi}{\omega},\quad \lambda=\frac{2\pi}{k},\quad f=\frac1T,\quad c=\lambda f.\]À position fixée, s se reproduit après T ; à date fixée, le profil se reproduit après λ. En une période, une crête parcourt une longueur d’onde.')+sub('Application',r'Un ultrason à 40,0 kHz dans l’air à 340 m/s possède T = 25,0 $\mu$s et λ = 8,50 mm. Une lumière de longueur d’onde dans le vide 600 nm a une fréquence proche de $5{,}00\times10^{14}$ Hz. Les échelles diffèrent de nombreux ordres de grandeur, mais la relation reste la même.'))
 c.c('Déphasage dû à la propagation',box('loi','Retard et phase',r'Pour B en aval de A dans une propagation vers +x :\[\varphi_B-\varphi_A=-k(x_B-x_A)=-\omega\tau\pmod{2\pi}.\]Deux points sont en phase si leur séparation est un multiple de λ ; en opposition si elle vaut un multiple impair de λ/2.')+sub('L’ambiguïté des sinus',r'Un déphasage de $-\pi/2$ peut correspondre aux retards T/4, 5T/4, 9T/4, etc. Une mesure à une seule fréquence ne suffit donc pas à connaître un grand retard sans information supplémentaire. Une salve, un déplacement progressif du capteur ou plusieurs fréquences permettent de lever l’ambiguïté.')+sub('Exemple résolu',r'À 1 kHz, une phase relative $-90^\circ$ donne $\tau=0{,}25$ ms modulo 1 ms. Si la distance est voisine de 0,425 m et c voisine de 340 m/s, le retard plausible est 1,25 ms. Déduire c du retard minimal de 0,25 ms donnerait une valeur cinq fois trop grande.')+box('methode','Dérouler une phase',r'Commencer avec les capteurs proches, puis les éloigner sans perdre la continuité de la courbe. Compter les tours complets de phase, en plus de l’angle affiché.'))
 c.c('Mesurer une célérité',sub('Retard d’une salve',r'Émettre une impulsion ou une salve courte ; enregistrer les deux capteurs sur la même base de temps ; mesurer leur distance ; comparer le même motif. Alors c = d/τ. Un pic de corrélation peut aider, mais il faut vérifier le sens du décalage et éviter de choisir un autre cycle du sinus.')+box('loi','Incertitude dans un modèle simple',r'Si d et τ ont des incertitudes-types indépendantes et petites :\[\frac{u(c)}c=\sqrt{\left(\frac{u(d)}d\right)^2+\left(\frac{u(\tau)}\tau\right)^2}.\]Une erreur systématique commune aux positions ou aux canaux demande un traitement distinct ; la formule ne remplace pas l’analyse du montage.')+sub('Mesure par λ et f',r'À fréquence fixe, déplacer un récepteur entre plusieurs positions en phase. Mesurer une distance correspondant à N longueurs d’onde et diviser par N réduit l’effet d’une incertitude de lecture sur les positions. Utiliser ensuite c = λf. Les réflexions parasites peuvent déplacer les maxima : éloigner les obstacles ou analyser une fenêtre temporelle avant leur retour.')+box('docu','Un résultat doit être comparé',r'Comparer à une valeur attendue pour le milieu et ses conditions. Conclure sur la compatibilité au regard des incertitudes, pas seulement sur l’égalité des chiffres affichés.'))
 c.c('Milieux transparents et non dispersifs',box('loi','Le modèle de translation',r'Un milieu transparent dans la bande étudiée transmet le signal avec une absorption négligeable. Un milieu non dispersif possède une vitesse de phase indépendante de la fréquence dans cette bande. Si toutes les composantes subissent le même retard et une transmission identique, le signal conserve sa forme.')+sub('Des hypothèses locales',r'Ces propriétés sont valables sur une bande et une distance données. Un milieu peut être faiblement dispersif sur une bande étroite et nettement dispersif sur une bande plus large. La lumière dans le vide est non dispersive ; le son dans l’air est souvent modélisé ainsi dans le domaine usuel. Une corde idéale sous tension constante fournit aussi un modèle non dispersif.')+sub('Atténuation et dispersion',r'Une amplitude qui décroît avec la distance signale une perte ou un étalement géométrique, sans prouver une dispersion. Une déformation peut résulter d’une absorption dépendant de la fréquence, d’une dispersion ou des deux. Pour isoler la dispersion, comparer les phases et les vitesses des composantes, en plus des amplitudes.')+box('piege','Ne pas généraliser sans bande',r'Les vagues à la surface de l’eau peuvent être dispersives ; leur célérité dépend du régime et de la longueur d’onde. Une valeur unique fournie dans un exercice peut être une hypothèse locale de modélisation.'))
 c.c('Comprendre la dispersion',fig('dispersion','Deux composantes ayant acquis une phase relative différente changent la forme du signal, même avec des amplitudes inchangées.')+sub('La vitesse de phase',r'Pour une composante sinusoïdale, $v_\varphi=\omega/k$. Dans un milieu dispersif, k dépend de ω autrement que par une proportionnalité de coefficient constant. Chaque composante accumule donc une phase différente de celle d’une translation unique.')+box('loi','Une loi fournie suffit',r'Si deux composantes de fréquences $f_1$ et $f_2$ se propagent à des vitesses c1 et c2, leurs phases après d sont $-2\pi f_1d/c_1$ et $-2\pi f_2d/c_2$. Un même retard décrirait les deux seulement si $d/c_1=d/c_2$, à l’ambiguïté périodique près.')+sub('Ce que l’on n’en déduit pas',r'La vitesse de phase d’une composante ne suffit pas à connaître la vitesse d’un front ou d’une enveloppe dans un milieu dispersif. Ici, on se limite à comparer les composantes et leur déformation ; une théorie du paquet d’ondes demande d’autres outils.'))
 c.c('Une méthode complète sur un signal réel',sub('Étape 1 : annoncer le modèle',r'Préciser le milieu, l’axe, la grandeur mesurée et l’intervalle où l’on néglige pertes et dispersion. Si un mur renvoie une onde, la mesure ne correspond plus à une onde progressive unique. Choisir si possible les dates antérieures au retour de l’écho.')+sub('Étape 2 : choisir la bonne fonction',r'Une source f(t) impose $f(t-x/c)$ pour une propagation vers +x. Un profil initial F(x) impose F(x-ct). Dans les deux cas, vérifier le déplacement d’un maximum ou l’arrivée du front. Pour une source démarrant à zéro, conserver la condition de support de f.')+sub('Étape 3 : relier les observations',r'Passer d’une distance à un retard, d’une fréquence à une longueur d’onde et d’un retard à une phase. Utiliser plusieurs observations pour vérifier c : une salve donne le retard absolu, tandis qu’un sinus donne une mesure fine modulo sa période.')+box('methode','Une phrase de conclusion utile',r'« Les signaux sont compatibles avec une translation de délai τ dans la bande étudiée. La célérité déduite est c, avec son incertitude. Les différences résiduelles de forme limitent le modèle. » Cette conclusion distingue le résultat mesuré de l’hypothèse d’absence de dispersion.')+box('docu','Vers le chapitre 9',r'Quand deux ondes atteignent le même point, la somme dépend de leur phase relative. Le déphasage de propagation devient alors le mécanisme des interférences.'))
 c.tp_title='Mesurer la célérité des ultrasons'
 c.tp=fig('capteurs','Deux récepteurs évitent de confondre délai électronique d’émission et délai de propagation entre les points de mesure.')+sub('Deux méthodes',r'Utiliser une salve à 40 kHz. Relever le retard entre deux récepteurs séparés de d, puis répéter pour plusieurs distances. Ajuster τ = d/c + τ0 : la pente donne 1/c et l’ordonnée teste un décalage des voies. En émission continue, mesurer ensuite une distance couvrant dix retours en phase pour obtenir λ.')+sub('Données simulées et exploitation',r'Pour d = 0,170 ; 0,340 ; 0,510 m, on donne τ = 0,520 ; 1,020 ; 1,520 ms. La pente vaut 2,941 ms/m, donc c = 340 m/s ; l’offset est 20 $\mu$s. Utiliser d/τ sans retirer l’offset sous-estimerait c. Dix longueurs d’onde doivent mesurer 85,0 mm à 40,0 kHz.')+box('methode','Compte rendu attendu',r'Donner les points et résidus de l’ajustement, le choix de l’événement temporel, les incertitudes de position et de temps, la comparaison des deux méthodes et l’effet possible des réflexions. Ces données sont créées pour l’entraînement.')
 c.num_title='Translater une impulsion sans équation d’onde'
 c.num=r'''On calcule directement la fonction retardée d’une source gaussienne. La source est définie pour tout temps ; il s’agit d’un modèle mathématique d’impulsion, sans front abrupt.
\begin{verbatim}
import numpy as np
import matplotlib.pyplot as plt
c = 2.
t = np.linspace(-1, 6, 7001)
def source(t):
    return np.exp(-((t-1)/0.2)**2)
signals = {}
for x in (0., 2., 5.):
    s = source(t-x/c)
    signals[x] = s
    plt.plot(t, s, label=f"x={x} m")
plt.xlabel("t (s)"); plt.ylabel("s / A")
plt.grid(); plt.legend(); plt.tight_layout()
peaks = {x: t[s.argmax()] for x,s in signals.items()}
\end{verbatim}
Les maxima sont à 1,0 ; 2,0 ; 3,5 s. Les différences de dates valent les différences de positions divisées par c. Construire ensuite les profils spatiaux $s(x,t)$ à deux instants : les maxima doivent être distants de $c\Delta t$. Doubler c divise les retards par deux, sans changer la durée de l’impulsion émise. Une largeur spatiale, elle, est multipliée par c.
'''
 bilan(c,r'Vers +x : F(x-ct) ou f(t-x/c). Vers -x : G(x+ct) ou g(t+x/c). $\tau=d/c$, $\lambda=c/f$, $k=2\pi/\lambda=\omega/c$, $\Delta\varphi=-\omega\tau$ en aval.',r'Faire un dessin de l’axe ; suivre un événement ; légender espace et temps ; traiter les fronts ; lever les tours de phase ; comparer plusieurs mesures et annoncer le domaine du modèle.',r'Lire une photographie comme un chronogramme ; confondre la vitesse d’un point de corde et c ; prendre la phase minimale pour un retard absolu ; oublier les conversions ms, μs et mm ; attribuer toute déformation à la dispersion.')
 c.td_titles=['Grandeurs et ordres de grandeur','Retards et impulsions','Écrire une propagation','Périodes et phase','Mesurer une célérité','Lever les ambiguïtés','Dispersion et modèles','Interpréter une expérience']
 exercices(c,[
 ('Le son et la lumière',r'Comparer le temps de parcours de 1 km par le son à 340 m/s et par la lumière à $3\times10^8$ m/s.',r'$t_s=1000/340=2{,}941$ s ; $t_l=3{,}333\ \mu$s. Pour une observation d’orage à cette distance, le délai visuel est négligeable devant le délai sonore.'),
 ('Identifier le signal',r'Donner une grandeur et son unité pour une onde sur une corde, une onde acoustique et un signal électrique dans un câble.',r'Déplacement transversal y en m ; surpression p en Pa ; tension u en V, ou courant i en A. Ces grandeurs ne sont pas la célérité, exprimée en m/s.'),
 ('Un ultrason',r'f = 40 kHz et c = 340 m/s. Déterminer T, ω et λ.',r'T = 25 $\mu$s ; $\omega=80000\pi=2{,}5133\times10^5$ rad/s ; λ = 8,50 mm. Le domaine est ultrasonore.'),
 ('Un retard court',r'Deux capteurs sont séparés de 0,510 m et reçoivent la même salve avec un retard de 1,50 ms. Calculer c.',r'$c=0{,}510/(1{,}50\times10^{-3})=340$ m/s. Cette valeur suppose que le délai des deux voies est identique ou corrigé.'),
 ('Un écho',r'Un écho revient 0,80 s après l’émission, avec c = 340 m/s. Quelle est la distance de l’obstacle ?',r'Le signal parcourt l’aller-retour : $2d=c\Delta t$. Donc d = 136 m. Employer $d=c\Delta t$ compterait deux fois la distance recherchée.'),
 ('Durée et longueur',r'Une impulsion dure 0,20 s à la source et se propage à 3 m/s. Quelle longueur occupe-t-elle ?',r'$\ell=c\Delta t=0{,}60$ m dans le modèle sans déformation. Sa durée de passage devant chaque point reste 0,20 s.'),
 ('Une bosse vers la droite',r'À t = 0, $s=A\exp[-(x-1)^2/a^2]$. Écrire le signal à c = 2 m/s vers +x et donner son centre à t = 3 s.',r'$s=A\exp[-(x-1-2t)^2/a^2]$. Le centre vérifie x - 1 - 2t = 0, donc x = 7 m à t = 3 s.'),
 ('Une bosse vers la gauche',r'Même profil initial que E07, se propageant vers -x à 2 m/s. Où est le maximum à t = 1 s ?',r'$s=A\exp[-(x-1+2t)^2/a^2]$. Le centre est x = 1 - 2t, donc -1 m. Le signe +ct dans l’argument correspond bien à une propagation vers les x décroissants.'),
 ('Une source mise en route',r'$f(t)=0$ pour t < 0 et $A\sin\omega t$ pour t ≥ 0. Écrire la réception à x > 0 vers +x.',r'Le signal vaut 0 pour t < x/c puis $A\sin[\omega(t-x/c)]$ pour t ≥ x/c. Le front arrive à x/c ; le sinus seul sans cette condition serait acausal pour cette émission.'),
 ('Lire une expression',r'$s=0{,}002\cos(100\pi t-5\pi x)$, en unités SI. Donner A, f, λ et c.',r'A = 2 mm ; f = 50 Hz ; k = 5π rad/m ; λ = 0,40 m ; c = ω/k = 20 m/s. La propagation est vers +x.'),
 ('Une phase constante',r'Pour $s=A\cos(\omega t+kx)$, dériver la condition de phase constante. Quel est le sens ?',r'$\omega\dd t+k\dd x=0$ donne $\dd x/\dd t=-\omega/k$. Si k et ω sont positifs, la propagation est vers -x.'),
 ('Deux photographies',r'Une crête passe de x = 1,2 m à x = 2,0 m en 40 ms. L’écart entre deux crêtes est 0,50 m. Déterminer c et f.',r'c = 0,80/0,040 = 20 m/s. $f=c/\lambda=40$ Hz. La fréquence provient de la double périodicité, pas du nombre de crêtes photographiées.'),
 ('Un quart de longueur d’onde',r'Deux points sont séparés de λ/4 dans le sens de propagation. Donner retard et phase relative.',r'$\tau=(\lambda/4)/c=T/4$. La phase du point aval moins celle du point amont vaut $-\pi/2$ modulo $2\pi$. Le point aval retarde.'),
 ('Une séparation en phase',r'À f = 500 Hz et c = 340 m/s, donner la plus petite séparation positive entre points en phase puis en opposition.',r'λ = 0,680 m. En phase : λ = 0,680 m ; en opposition : λ/2 = 0,340 m. Des séparations plus grandes peuvent satisfaire les mêmes phases.'),
 ('Une mesure sur dix périodes spatiales',r'Dix longueurs d’onde occupent 84,8 mm à f = 40,0 kHz. Déterminer c.',r'λ = 8,48 mm ; c = 0,00848 × 40000 = 339,2 m/s. Le comptage porte sur dix intervalles, donc onze positions si l’on marque chaque retour en phase.'),
 ('Propager une incertitude',r'd = 0,680 m avec u(d) = 0,002 m ; τ = 2,00 ms avec u(τ) = 0,01 ms, indépendantes. Donner c et u(c).',r'c = 340 m/s. L’incertitude relative vaut $\sqrt{(0{,}002/0{,}680)^2+(0{,}01/2)^2}=0{,}00580$. Donc u(c) = 1,97 m/s, à présenter par exemple 340,0 ± 2,0 m/s en incertitude-type.'),
 ('Un décalage de voies',r'Un ajustement donne τ = 0,020 ms + 2,94 ms/m × d. Déterminer c et interpréter l’ordonnée.',r'La pente vaut $2{,}94\times10^{-3}$ s/m, donc c = 340,14 m/s. L’ordonnée 20 μs peut représenter un décalage instrumental ; elle ne correspond pas à un temps de parcours proportionnel à d.'),
 ('Un câble rapide',r'Un signal électrique parcourt 30 m en 150 ns. Déterminer sa célérité et la fraction de $c_0=3\times10^8$ m/s.',r'c = $30/(150\times10^{-9})=2\times10^8$ m/s, soit $2c_0/3$. Il faut une description de propagation plutôt qu’une transmission instantanée à cette échelle temporelle.'),
 ('L’ambiguïté d’un angle',r'À 1 kHz, le retard de phase mesuré est 90° ; d = 0,425 m. Donner les deux plus petits retards compatibles et la célérité plausible pour le son.',r'Les retards positifs sont 0,25 ms, 1,25 ms, 2,25 ms, etc. Les deux premiers donneraient 1700 puis 340 m/s. L’ordre de grandeur sonore sélectionne 1,25 ms ; une salve doit confirmer ce choix.'),
 ('Deux ondes sismiques',r'Les vitesses P et S sont 8,0 et 4,5 km/s. L’onde S arrive 180 s après P. Donner la distance au foyer dans un modèle de trajets identiques.',r'$\Delta t=d(1/c_S-1/c_P)$, donc d = $180/(1/4{,}5-1/8)=1851{,}4$ km. Le modèle homogène et les trajets communs sont des simplifications ; une seule station ne donne pas une position complète.'),
 ('Deux vitesses de phase',r'Une composante à 100 Hz se propage à 10 m/s et celle à 200 Hz à 12 m/s. Le milieu est-il dispersif ? Donner leurs longueurs d’onde.',r'Oui, les vitesses de phase diffèrent. λ1 = 0,10 m et λ2 = 0,060 m. La seule différence de longueurs d’onde ne prouverait pas la dispersion : dans un milieu non dispersif elles varient déjà comme 1/f.'),
 ('Une atténuation sans dispersion',r'Une impulsion perd la moitié de son amplitude sur 10 m mais conserve sa forme et son retard relatif. Peut-on conclure à une dispersion ?',r'Non. Une atténuation commune à toutes ses composantes peut réduire l’amplitude sans déformer le profil. Il faut analyser la dépendance fréquentielle de la vitesse ou les déphasages pour établir une dispersion.'),
 ('Un profil à reconstruire',r'Un triangle s’étend de x = 1 à 5 m à t = 0, maximum A à x = 2 m. Il avance à 2 m/s. Donner les trois dates caractéristiques au capteur x = 9 m.',r'Le bord droit x = 5 arrive à 2 s ; le maximum x = 2 à 3,5 s ; le bord gauche x = 1 à 4 s. L’enregistrement monte de 0 à A entre 2 et 3,5 s puis redescend entre 3,5 et 4 s.'),
 ('Tester le modèle par la forme',r'Deux récepteurs donnent des signaux dont les maxima ont le même retard, mais la seconde impulsion est plus large. Le modèle de translation exacte suffit-il ?',r'Non : une translation conserve la largeur. La dispersion, une absorption sélective ou les réponses instrumentales peuvent élargir le signal. Comparer les spectres et permuter les récepteurs aide à séparer les causes. Un seul retard de maximum ne valide pas toute la forme.')])
 c.d('Identifier une célérité et un retard instrumental',r'Des mesures simulées donnent d = 0,20 ; 0,40 ; 0,60 ; 0,80 m et τ = 0,610 ; 1,200 ; 1,790 ; 2,380 ms. On suppose τ = d/c + τ0.'+qs(r'Identifier c et τ0 à partir des deux points extrêmes ; vérifier les intermédiaires.',r'Comparer avec c obtenu par d/τ au premier point.',r'Chaque date extrême a une incertitude-type indépendante de 5 μs ; les distances sont ici supposées exactes. Estimer u(c).',r'Proposer une manipulation qui distingue retard électronique et propagation. Pourquoi des points parfaitement alignés ne prouvent-ils pas l’absence de biais ?'),'1. Utiliser la différence des retards. 2. Propager u(Δτ). 3. Une translation verticale de tous les points ne change pas la pente.',r'La pente est $(2{,}380-0{,}610)/0{,}60=2{,}950$ ms/m ; c = 338,983 m/s. $\tau_0=0{,}610-0{,}20\times2{,}950=0{,}020$ ms. Les deux autres points sont sur la même droite. Au premier point, d/τ = 327,87 m/s, biaisé vers le bas. $u(\Delta\tau)=\sqrt2\times5=7{,}071\ \mu$s ; $u(c)/c=u(\Delta\tau)/\Delta\tau=0{,}003995$, donc u(c) = 1,354 m/s. Permuter les voies et placer les capteurs côte à côte permet de tester le décalage instrumental. Une erreur d’étalonnage de la distance ou de la base de temps peut conserver une excellente linéarité tout en biaisant la pente. La qualité d’un ajustement et la justesse d’une mesure sont deux questions distinctes.')
 c.d('Un sonar avec deux trajets',r'Un sonar au repos émet une salve brève dans l’eau, de célérité c = 1500 m/s. Un écho direct sur le fond revient à 0,120 s. Un second retour, à 0,160 s, est attribué à un trajet de longueur totale supérieure de 60 m.'+qs(r'Déterminer la profondeur déduite du premier écho.',r'Le second temps est-il compatible avec la différence de trajet annoncée ?',r'La salve dure 2,0 ms : quelle séparation de profondeur correspond à cette durée d’aller-retour ?',r'Une oscillation interne à 100 kHz peut-elle donner seule la profondeur absolue ? Expliquer le rôle de l’enveloppe.',r'Comment une mauvaise valeur de c affecte-t-elle la profondeur ?'),'1. L’écho parcourt deux fois la profondeur. 2. Comparer cΔt à 60 m. 3. La phase d’un sinus ne donne qu’un retard modulo T.',r'La profondeur est h = cτ/2 = 90 m. Le supplément de trajet est $1500(0{,}160-0{,}120)=60$ m : les données sont cohérentes. Une durée de 2 ms correspond à une séparation de profondeur cΔt/2 = 1,50 m ; c’est un ordre de grandeur de séparation temporelle dans ce protocole, pas une résolution universelle indépendante du traitement. À 100 kHz, T = 10 μs, ce qui laisse une ambiguïté de distance aller-retour de 15 mm et de profondeur de 7,5 mm entre deux cycles ; on ne connaît pas le nombre de cycles parcourus par la seule phase. L’enveloppe de la salve fournit le retard absolu. Une erreur relative sur c se transmet directement à h si τ est fixé. La célérité doit être adaptée aux conditions du milieu.')
 c.d('Deux fréquences dans un milieu dispersif',r'Une source émet $s(0,t)=\cos(2\pi100t)+0{,}5\cos(2\pi200t)$. Les vitesses de phase sont c1 = 10 m/s et c2 = 12 m/s. L’amplitude de chaque composante est supposée conservée.'+qs(r'Écrire s(d,t) pour une distance d.',r'À d = 0,30 m, calculer les deux retards de phase et les phases acquises.',r'Comparer la sortie avec une simple translation de l’entrée de retard d/c1.',r'Peut-on déduire de ces deux seules vitesses la vitesse d’un front abrupt ?'),'1. Propager chaque raie. 2. Le retard du premier harmonique n’est pas celui du second. 3. Un front abrupt contient d’autres fréquences.',r'$s(d,t)=\cos[2\pi100(t-d/10)]+0{,}5\cos[2\pi200(t-d/12)]$. À d = 0,30 m, τ1 = 30 ms et τ2 = 25 ms ; les phases acquises sont -6π et -10π, toutes deux équivalentes à zéro. À cette distance particulière, le signal reçu est donc identique à l’entrée ; il coïncide aussi avec son retard de 30 ms, qui vaut trois périodes fondamentales. Cette coïncidence n’invalide pas la dispersion : les vitesses diffèrent, mais les phases retombent sur des tours entiers. À d = 0,31 m, une translation unique ne convient plus en général. Le profil peut ainsi se reformer à certaines distances. Deux vitesses à deux fréquences ne déterminent pas le comportement d’un front, qui nécessite une information spectrale beaucoup plus large.')
 c.dm_title='DM — Retrouver une impulsion'
 c.dm=r'À t = 0, une corde porte un triangle : y = 0 hors de [1 m ; 5 m], montée linéaire de 0 à A = 2 cm entre 1 et 2 m, puis descente linéaire jusqu’à 0 entre 2 et 5 m. La perturbation se propage vers +x à c = 2 m/s.'+sub('A. Profil — 7 points',qs(r'Écrire F(x) par morceaux, puis y(x,t). (4)',r'Donner support et maximum à t = 1,5 s ; construire le profil. (3)'))+sub('B. Enregistrement — 9 points',qs(r'Au point x = 9 m, déterminer début, maximum et fin du passage. (3)',r'Écrire y(9,t) par morceaux et tracer son allure. (4)',r'Comparer les durées de montée temporelle et spatiale. (2)'))+sub('C. Capteurs — 4 points',qs(r'Un autre capteur est à x = 11 m. Donner le retard et écrire la relation entre les deux enregistrements. (2)',r'Que contrôler si le deuxième signal est plus large ? (2)'))
 c.dm_sol=sub('A — 7 points',r'$F(x)=A(x-1)/(1\ \mathrm m)$ entre 1 et 2 m, $F(x)=A(5-x)/(3\ \mathrm m)$ entre 2 et 5 m, et zéro ailleurs ; y = F(x-2t), avec x et t en SI (4). À 1,5 s, le support est [4 ; 8] m et le maximum en 5 m, d’amplitude inchangée (3).')+sub('B — 9 points',r'Au point 9 m : début 2 s, maximum 3,5 s, fin 4 s (3). Pour 2 ≤ t ≤ 3,5 s : $y=A(2t-4)/3$, en utilisant les valeurs numériques de t en secondes. Pour 3,5 ≤ t ≤ 4 s : $y=A(8-2t)$. Hors de cet intervalle y = 0 (4). La montée temporelle dure 1,5 s, car le flanc spatial droit, long de 3 m, arrive d’abord ; la descente dure 0,5 s. Ce n’est pas le flanc spatial gauche qui passe en premier (2).')+sub('C — 4 points',r'Le retard supplémentaire vaut (11 - 9)/2 = 1 s ; $y(11,t)=y(9,t-1)$ (2). Une largeur différente impose de tester dispersion, pertes sélectives, réflexions et réponses des capteurs ; permuter les capteurs est un contrôle utile (2).')
 c.ds_title='DS — Mesurer une onde sonore'
 c.ds=[sub('A. Identifier l’onde — 7 points',r'La surpression vaut $p(x,t)=0{,}80\cos(4000\pi t-\frac{200\pi}{17}x)$ Pa, en unités SI.'+qs(r'Donner amplitude, pulsation, fréquence, k, λ, c et sens de propagation. (4)',r'Déterminer la phase du point B situé 0,255 m après A et le retard correspondant. (3)'))+sub('B. Mesure par salve — 7 points',r'Deux capteurs séparés de d = 0,680 m enregistrent un retard de 2,04 ms. Le décalage propre des voies est +40 μs, ajouté au temps physique.'+qs(r'Corriger le retard et calculer c. (3)',r'Avec u(d) = 2 mm et u(τ corrigé) = 10 μs, indépendants, calculer u(c). (2)',r'Expliquer l’intérêt d’un ajustement sur plusieurs distances. (2)')),
 sub('C. Une propagation différente — 6 points',r'Un second dispositif transmet 1 kHz à 300 m/s et 2 kHz à 330 m/s.'+qs(r'Le milieu est-il dispersif ? Calculer les deux longueurs d’onde. (2)',r'Écrire le signal à x pour une source $s(0,t)=\cos(2\pi1000t)+0{,}5\cos(2\pi2000t)$. (2)',r'Pourquoi un retard unique n’est-il généralement pas suffisant ? Une perte d’amplitude prouverait-elle la dispersion ? (2)'))]
 c.ds_sol=[sub('A — 7 points',r'A = 0,80 Pa, ω = 4000π rad/s, f = 2000 Hz, k = 200π/17 rad/m, λ = 0,170 m, c = 340 m/s ; propagation vers +x (4). d = 1,5λ, donc phase B - A = -3π, équivalente à π ; retard d/c = 0,750 ms, soit 1,5 période (3).')+sub('B — 7 points',r'Le retard physique vaut 2,04 ms - 0,04 ms = 2,00 ms ; c = 340 m/s (3). L’incertitude relative vaut \[\sqrt{(0{,}002/0{,}680)^2+(0{,}01/2)^2}.\]u(c) = 1,97 m/s (2). La pente τ(d) donne 1/c et l’ordonnée permet de repérer un délai fixe ; les résidus testent la linéarité dans la plage mesurée (2).'),sub('C — 6 points',r'Les vitesses de phase diffèrent : milieu dispersif. λ1 = 0,300 m, λ2 = 0,165 m (2). $s(x,t)=\cos[2\pi1000(t-x/300)]+0{,}5\cos[2\pi2000(t-x/330)]$ (2). Les deux composantes n’ont pas le même retard x/c, donc leur phase relative évolue et la forme se déforme en général. Une atténuation seule ne prouve pas la dispersion, car elle peut agir sans changement de vitesse (2).')]
 c.hints='E05 : compter l’aller-retour. E08 : suivre le maximum. E16 : propager les incertitudes relatives. E19 : ajouter des périodes entières. E23 : le bord droit passe d’abord.'
 c.eval_hints='DM : commencer par les trois sommets du triangle. DS : corriger le retard instrumental avant la division ; annoncer si une phase est donnée modulo 2π.'
 c.source('TD publié — Deux arrivées sismiques',TD9,'TD9, 2025–2026, exercice 3, p. 1.',r'Traiter les deux questions. Dessiner les trajets supposés communs et distinguer distance déterminée et localisation spatiale.',r'La différence d’arrivée vérifie $\Delta t=d(1/c_S-1/c_P)$. Les données donnent environ 1850 km. Une seule différence de temps fournit une distance dans ce modèle ; plusieurs stations sont nécessaires pour localiser le foyer, avec un modèle de propagation adapté.')
 c.source('DS publié — Une cuve à ondes',DS5,'DS5 du 21 janvier 2026, exercice 2, partie I, questions 1 à 4, p. 2.',r'Exprimer les paramètres de l’onde puis tracer les trois enregistrements sur une base temporelle commune. Ne pas généraliser l’hypothèse non dispersive à toutes les vagues.',r'Les valeurs fournies donnent λ = 3,6 mm et k = 2π/λ. La phase à 3λ/4 retarde de 3π/2 ; à 5λ, les signaux sont en phase. La fonction retardée conserve l’amplitude et la fréquence dans le modèle annoncé.')
 c.next='Le chapitre 9 superpose deux ondes et relie leurs chemins au déphasage d’interférence.'
 c.check('incertitude-c',340*sqrt((.002/.680)**2+(.01/2)**2),1.972308292331602,1e-6)
 c.check('distance-sismique',180/(1/4.5-1/8),1851.4285714285716)
 c.check('D1-c',.6/.00177,338.9830508474576)
 c.check('TP-c',.34/.001,340)
 return c
